"use client";

import { Slot as SlotPrimitive } from "radix-ui";
import { cva, type VariantProps } from "class-variance-authority";
import type * as React from "react";
import { cn } from "@/lib/utils";

/**
 * Button (button-radix)
 *
 * A button with seven visual variants and four sizes, built on a native button element with an optional asChild slot for links.
 *
 * Exports: Button, buttonVariants
 *
 * Props:
 * - Button: React.ComponentProps<"button"> & VariantProps<typeof buttonVariants> & { asChild?: boolean; }
 *   - variant: "default" | "accent" | "destructive" | "outline" | "secondary" | "ghost" | "link" (default "default"). Selects the variant styles defined by buttonVariants.
 *   - size: "default" | "sm" | "lg" | "icon" (default "default"). Selects the size styles defined by buttonVariants.
 *   - asChild: boolean (default false). Render the single child element instead of the default element, merging props onto it (Radix Slot).
 *
 * Theme tokens (shadcn names, from your theme): --accent, --accent-foreground, --background, --destructive, --input, --primary, --primary-foreground, --radius, --ring, --secondary, --secondary-foreground.
 * Component variables (shipped in this item's cssVars, light and dark): --button-destructive-foreground, --button-font-size, --button-radius.
 *
 * Accessibility:
 * - Renders a native button with type="button" by default, so Enter and Space activate it and it never submits a form by accident.
 * - Focus is always visible through a 3px ring in the ring color.
 * - Disabled buttons ignore pointer events and dim to 50% opacity; explain why nearby when the reason is not obvious.
 * - Icon-only buttons (size "icon") need an aria-label.
 * - The press scale is skipped under prefers-reduced-motion.
 *
 * Customize:
 * - Edit or add variants and sizes in buttonVariants; every color comes from theme tokens such as bg-primary, bg-accent, and bg-destructive.
 * - Change the corner radius and label size through the button's own radius and font-size variables, which ship with this item.
 * - Use asChild to give a link or router component button styling.
 * - Set the data-no-press-scale attribute to turn off the press scale on one button.
 */

const buttonVariants = cva(
  "inline-flex shrink-0 cursor-pointer items-center justify-center gap-2 whitespace-nowrap rounded-[var(--button-radius)] font-medium text-[length:var(--button-font-size)] outline-none transition-[background-color,border-color,color,transform,box-shadow,opacity] duration-150 ease-out focus-visible:ring-[3px] focus-visible:ring-ring/50 active:scale-[0.97] disabled:pointer-events-none disabled:opacity-50 data-[no-press-scale]:active:scale-100 motion-reduce:transition-none motion-reduce:active:scale-100 [&_svg:not([class*='size-'])]:size-4 [&_svg]:pointer-events-none",
  {
    variants: {
      variant: {
        default:
          "bg-primary text-primary-foreground shadow-xs hover:bg-primary/90",
        accent: "bg-accent text-accent-foreground shadow-xs hover:bg-accent/90",
        destructive:
          "bg-destructive text-(--button-destructive-foreground) shadow-xs hover:bg-destructive/90",
        outline:
          "border border-input bg-background shadow-xs hover:bg-secondary hover:text-secondary-foreground",
        secondary:
          "bg-secondary text-secondary-foreground shadow-xs hover:bg-secondary/80",
        ghost: "hover:bg-secondary hover:text-secondary-foreground",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "h-9 px-4 py-2 has-[>svg]:px-3",
        sm: "h-8 gap-1.5 px-3 has-[>svg]:px-2.5",
        lg: "h-10 px-6 has-[>svg]:px-4",
        icon: "size-9",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
);

function Button({
  className,
  variant,
  size,
  asChild = false,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean;
  }) {
  const Comp = asChild ? SlotPrimitive.Slot : "button";
  return (
    <Comp
      className={cn(buttonVariants({ variant, size, className }))}
      data-slot="button"
      type={asChild ? undefined : "button"}
      {...props}
    />
  );
}

export { Button, buttonVariants };
